// Core tests: the 7 literal core cases from the fixed spec's
// fixtures.json (vendored verbatim at test/fixtures.json from spec
// candidate f02756da51344f143425657d3bcefc478e1da521; expected values
// taken verbatim, never generated by the product), plus hand-derived
// endpoint, exact-multiple, display-tie, ignored-field, and
// validation-order cases. The SPEC's own rules are the oracle; every
// extra expected value below was computed by hand from those rules
// (bag ratios for the fixture inputs are also listed in the spec's
// AUTHOR-CHECK for cross-checking).

import assert from "node:assert/strict";
import test from "node:test";
import { run } from "../public/js/core/concrete.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const slabBase = {
  shape: "slab",
  lengthCm: "400",
  widthCm: "300",
  thicknessCm: "10",
  depthCm: "30",
  diameterCm: "30",
  heightCm: "200",
  count: "1",
  wastePct: "10",
};
const errorOf = (input) => run(input).error;

// Hand-derived: the waste-crossing slab (200x100x5 cm) at waste 0%.
// The spec's AUTHOR-CHECK lists the 0% bag ratios 11.771556 /
// 7.847704 / 5.885778 -> 12 / 8 / 6, and 0.1 m3 = 0.131 yd3.
test("hand-derived: waste-crossing slab at waste 0%", () => {
  assert.deepEqual(
    run({ ...slabBase, lengthCm: "200", widthCm: "100", thicknessCm: "5", wastePct: "0" }),
    {
      ok: true,
      result: {
        shape: "slab",
        count: 1,
        netVolumeM3: "0.100",
        adjustedVolumeM3: "0.100",
        adjustedVolumeYd3: "0.131",
        bags: { bag40: 12, bag60: 8, bag80: 6 },
      },
    },
  );
});

// Hand-derived exact-multiple case (the SPEC's "no round-up when the
// adjusted volume is an exact multiple of a yield" synthetic case):
// the yield numerators factor as 2^9 * 3^4 * 127^3 (40 lb), with
// 60 lb = 1.5x and 80 lb = 2x the 40 lb yield. Dimensions
// 650.24 = 512*127, 102.87 = 81*127, 158.75 = 125*127 hundredths make
// the adjusted volume exactly 1250 x yield40 = 625 x yield80, so
// bag40 = 1250 and bag80 = 625 exactly (no ceiling bump), while
// bag60 = ceil(1250 / 1.5) = 834. Volume 10.618817472 m3 -> "10.619";
// yd3 = 13.889.
test("hand-derived: exact yield multiples do not round up", () => {
  assert.deepEqual(
    run({
      ...slabBase,
      lengthCm: "650.24",
      widthCm: "102.87",
      thicknessCm: "158.75",
      wastePct: "0",
    }),
    {
      ok: true,
      result: {
        shape: "slab",
        count: 1,
        netVolumeM3: "10.619",
        adjustedVolumeM3: "10.619",
        adjustedVolumeYd3: "13.889",
        bags: { bag40: 1250, bag60: 834, bag80: 625 },
      },
    },
  );
});

// Hand-derived legal endpoints together: dimensions 10000 cm,
// count 999, waste 100%. Unit volume 10^6 m3; net 999 * 10^6;
// adjusted doubles it. Bag counts computed by exact division.
test("hand-derived endpoints: max dimensions, count, and waste", () => {
  assert.deepEqual(
    run({
      ...slabBase,
      lengthCm: "10000",
      widthCm: "10000",
      thicknessCm: "10000",
      count: "999",
      wastePct: "100",
    }),
    {
      ok: true,
      result: {
        shape: "slab",
        count: 999,
        netVolumeM3: "999000000.000",
        adjustedVolumeM3: "1998000000.000",
        adjustedVolumeYd3: "2613285337.390",
        bags: { bag40: 235195680366, bag60: 156797120244, bag80: 117597840183 },
      },
    },
  );
});

// Hand-derived display tie: 1 x 1 x 500 cm is exactly 0.0005 m3, which
// the SPEC's half-up rule displays as "0.001" (and 0.000654 yd3 also
// displays "0.001"); a nonzero volume always needs at least 1 bag.
test("hand-derived: exact 0.0005 display tie rounds up", () => {
  assert.deepEqual(
    run({ ...slabBase, lengthCm: "1", widthCm: "1", thicknessCm: "500", wastePct: "0" }),
    {
      ok: true,
      result: {
        shape: "slab",
        count: 1,
        netVolumeM3: "0.001",
        adjustedVolumeM3: "0.001",
        adjustedVolumeYd3: "0.001",
        bags: { bag40: 1, bag60: 1, bag80: 1 },
      },
    },
  );
});

// The SPEC's ordering property, checked over the fixture successes
// and the endpoint case: bag40 >= bag60 >= bag80 always.
test("bag ordering property: bag40 >= bag60 >= bag80", () => {
  const inputs = coreCases.filter((entry) => entry.expected.ok).map((entry) => entry.input);
  inputs.push({
    ...slabBase,
    lengthCm: "10000",
    widthCm: "10000",
    thicknessCm: "10000",
    count: "999",
    wastePct: "100",
  });
  for (const input of inputs) {
    const { bags } = run(input).result;
    assert.ok(bags.bag40 >= bags.bag60 && bags.bag60 >= bags.bag80, JSON.stringify(bags));
  }
});

test("fields of other shapes are ignored completely, even when invalid", () => {
  // Slab: depth/diameter/height carry garbage and empty strings, yet
  // the result is exactly the slab-default-waste fixture result.
  const slabFixture = coreCases.find((entry) => entry.id === "slab-default-waste");
  assert.deepEqual(
    run({ ...slabBase, depthCm: "not-a-number", diameterCm: "", heightCm: "-5" }),
    slabFixture.expected,
  );
  // Cylinder: the slab/footing fields are ignored the same way.
  const cylinderFixture = coreCases.find((entry) => entry.id === "cylinder-four");
  assert.deepEqual(
    run({
      shape: "cylinder",
      lengthCm: "abc",
      widthCm: "",
      thicknessCm: "0",
      depthCm: "99999999999999999999",
      diameterCm: "30",
      heightCm: "200",
      count: "4",
      wastePct: "10",
    }),
    cylinderFixture.expected,
  );
});

test("SCHEMA: non-objects, arrays, missing, extra, wrong types, accessors", () => {
  const schema = { code: "SCHEMA", path: "" };
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("slab"), schema);
  assert.deepEqual(errorOf(["slab"]), schema);
  const missing = { ...slabBase };
  delete missing.wastePct;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...slabBase, extra: "1" }), schema);
  assert.deepEqual(errorOf({ ...slabBase, count: 1 }), schema);
  assert.deepEqual(errorOf({ ...slabBase, shape: null }), schema);
  const withAccessor = { ...slabBase };
  Object.defineProperty(withAccessor, "count", {
    enumerable: true,
    get() {
      return "1";
    },
  });
  assert.deepEqual(errorOf(withAccessor), schema);
});

test("ENUM: unknown or empty shape, checked before any other field", () => {
  assert.deepEqual(errorOf({ ...slabBase, shape: "cube" }), { code: "ENUM", path: "/shape" });
  assert.deepEqual(errorOf({ ...slabBase, shape: "" }), { code: "ENUM", path: "/shape" });
  assert.deepEqual(errorOf({ ...slabBase, shape: "cube", count: "1000" }), {
    code: "ENUM",
    path: "/shape",
  });
});

test("validation order: shape fields in shape order, then count, then wastePct", () => {
  assert.deepEqual(errorOf({ ...slabBase, lengthCm: "0", widthCm: "0", count: "0" }), {
    code: "RANGE",
    path: "/lengthCm",
  });
  assert.deepEqual(errorOf({ ...slabBase, widthCm: "0", thicknessCm: "0" }), {
    code: "RANGE",
    path: "/widthCm",
  });
  assert.deepEqual(errorOf({ ...slabBase, count: "0", wastePct: "101" }), {
    code: "RANGE",
    path: "/count",
  });
  // Footing validates depthCm (not thicknessCm); cylinder diameterCm
  // before heightCm.
  assert.deepEqual(errorOf({ ...slabBase, shape: "footing", depthCm: "0", thicknessCm: "0" }), {
    code: "RANGE",
    path: "/depthCm",
  });
  assert.deepEqual(errorOf({ ...slabBase, shape: "cylinder", diameterCm: "0", heightCm: "0" }), {
    code: "RANGE",
    path: "/diameterCm",
  });
});

test("per-field order: INPUT_LIMIT, EMPTY, format, range", () => {
  assert.deepEqual(errorOf({ ...slabBase, lengthCm: "12345678901234567" }), {
    code: "INPUT_LIMIT",
    path: "/lengthCm",
  });
  assert.deepEqual(errorOf({ ...slabBase, thicknessCm: "" }), {
    code: "EMPTY",
    path: "/thicknessCm",
  });
  assert.deepEqual(errorOf({ ...slabBase, count: "" }), { code: "EMPTY", path: "/count" });
  assert.deepEqual(errorOf({ ...slabBase, wastePct: "" }), {
    code: "EMPTY",
    path: "/wastePct",
  });
  assert.deepEqual(errorOf({ ...slabBase, thicknessCm: "1.234" }), {
    code: "NUMBER_FORMAT",
    path: "/thicknessCm",
  });
  assert.deepEqual(errorOf({ ...slabBase, count: "1.5" }), {
    code: "INTEGER_FORMAT",
    path: "/count",
  });
});

test("decimal grammar rejects signs, spaces, leading zeros, exponents, full-width digits", () => {
  for (const bad of ["010", "00.5", "1.", ".5", "+10", "-10", " 10", "10 ", "1e2", "１０", "1,000"]) {
    assert.deepEqual(
      errorOf({ ...slabBase, thicknessCm: bad }),
      { code: "NUMBER_FORMAT", path: "/thicknessCm" },
      `thicknessCm ${JSON.stringify(bad)}`,
    );
  }
  // A lone surrogate is a format failure, never a crash.
  assert.deepEqual(errorOf({ ...slabBase, thicknessCm: "\uD800" }), {
    code: "NUMBER_FORMAT",
    path: "/thicknessCm",
  });
});

test("range edges just outside each bound", () => {
  assert.deepEqual(errorOf({ ...slabBase, thicknessCm: "10000.01" }), {
    code: "RANGE",
    path: "/thicknessCm",
  });
  assert.deepEqual(errorOf({ ...slabBase, thicknessCm: "0.00" }), {
    code: "RANGE",
    path: "/thicknessCm",
  });
  assert.deepEqual(errorOf({ ...slabBase, count: "0" }), { code: "RANGE", path: "/count" });
  assert.deepEqual(errorOf({ ...slabBase, wastePct: "100.01" }), {
    code: "RANGE",
    path: "/wastePct",
  });
  // wastePct "0" and "100" are the legal endpoints.
  assert.equal(run({ ...slabBase, wastePct: "0" }).ok, true);
  assert.equal(run({ ...slabBase, wastePct: "100" }).ok, true);
});

test("result values are strings for volumes and integers for counts and bags", () => {
  const outcome = run(slabBase);
  assert.equal(outcome.ok, true);
  assert.equal(typeof outcome.result.netVolumeM3, "string");
  assert.equal(typeof outcome.result.adjustedVolumeM3, "string");
  assert.equal(typeof outcome.result.adjustedVolumeYd3, "string");
  assert.ok(Number.isInteger(outcome.result.count));
  for (const value of Object.values(outcome.result.bags)) {
    assert.ok(Number.isInteger(value) && value >= 1);
  }
});
